[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@500;600;700&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
:root {
  --blue: #3861FB;
  --blue-hover: #2c54e0;
  --blue-light: #eef2ff;
  --navy: #0D1421;
  --gray: #808A9D;
  --gray-light: #C2C7D0;
  --green: #16c784;
  --green-bg: rgba(22,199,132,0.08);
  --red: #ea3943;
  --red-bg: rgba(234,57,67,0.08);
  --bg: #ffffff;
  --bg-secondary: #f8fafc;
  --bg-tertiary: #eff2f5;
  --border: #e2e8f0;
  --border-light: #f0f0f0;
  --text: #0D1421;
  --text-secondary: #808A9D;
  --text-tertiary: #a0a8b4;
  --font-display: 'Space Grotesk', sans-serif;
  --font-body: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 24px rgba(0,0,0,0.12);
  --radius: 8px;
  --radius-sm: 4px;
  --radius-lg: 12px;
  --transition: 150ms ease;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { font-size: 14px; scroll-behavior: smooth; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }

body {
  font-family: var(--font-body);
  color: var(--text);
  background: var(--bg);
  line-height: 1.5;
  min-height: 100vh;
}

a { color: var(--blue); text-decoration: none; }
a:hover { color: var(--blue-hover); }

button { cursor: pointer; font-family: inherit; border: none; background: none; font-size: inherit; }

input { font-family: inherit; }

.tabular-nums { font-variant-numeric: tabular-nums; }

/* ── Navigation ── */
.nav {
  position: sticky; top: 0; z-index: 100;
  background: var(--bg);
  border-bottom: 1px solid var(--border);
  backdrop-filter: blur(8px);
  background: rgba(255,255,255,0.95);
}
.nav-inner {
  max-width: 1440px; margin: 0 auto;
  display: flex; align-items: center; gap: 24px;
  padding: 0 24px; height: 56px;
}
.nav-brand {
  font-family: var(--font-display);
  font-weight: 700; font-size: 18px;
  color: var(--navy); white-space: nowrap;
  display: flex; align-items: center; gap: 8px;
}
.nav-brand svg { flex-shrink: 0; }
.nav-links { display: flex; align-items: center; gap: 4px; flex: 1; }
.nav-links a {
  padding: 6px 12px; border-radius: var(--radius-sm);
  color: var(--text); font-weight: 500; font-size: 13px;
  transition: background var(--transition), color var(--transition);
  white-space: nowrap;
}
.nav-links a:hover { background: var(--bg-tertiary); color: var(--blue); }
.nav-links a.active { color: var(--blue); }
.nav-auth { display: flex; align-items: center; gap: 8px; margin-left: auto; }
.btn-login {
  padding: 7px 16px; border-radius: var(--radius-sm);
  font-weight: 600; font-size: 13px; color: var(--text);
  transition: background var(--transition);
}
.btn-login:hover { background: var(--bg-tertiary); }
.btn-signup {
  padding: 7px 16px; border-radius: var(--radius-sm);
  font-weight: 600; font-size: 13px; color: #fff;
  background: var(--blue); transition: background var(--transition);
}
.btn-signup:hover { background: var(--blue-hover); }

/* ── Top Bar Metrics ── */
.top-bar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border);
  overflow-x: auto;
}
.top-bar-inner {
  max-width: 1440px; margin: 0 auto;
  display: flex; align-items: center; gap: 32px;
  padding: 10px 24px;
}
.metric { display: flex; align-items: center; gap: 6px; white-space: nowrap; }
.metric-label { color: var(--text-secondary); font-size: 12px; font-weight: 500; }
.metric-value { font-weight: 600; font-size: 13px; }
.metric-change { font-size: 12px; font-weight: 600; }
.metric-change.positive { color: var(--green); }
.metric-change.negative { color: var(--red); }
.metric-badge {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 2px 8px; border-radius: 12px; font-size: 11px; font-weight: 600;
}
.metric-badge.neutral { background: var(--bg-tertiary); color: var(--gray); }
.metric-badge.green { background: var(--green-bg); color: var(--green); }
.metric-divider { width: 1px; height: 24px; background: var(--border); flex-shrink: 0; }

/* ── Promo Banner ── */
.promo-banner {
  background: linear-gradient(135deg, #1a1f3a 0%, #2d1b4e 50%, #1a2f4a 100%);
  color: #fff; position: relative; overflow: hidden;
}
.promo-banner::before {
  content: ''; position: absolute; inset: 0;
  background: radial-gradient(ellipse at 30% 50%, rgba(56,97,251,0.15) 0%, transparent 60%);
  pointer-events: none;
}
.promo-inner {
  max-width: 1440px; margin: 0 auto;
  display: flex; align-items: center; justify-content: center;
  padding: 12px 24px; gap: 16px; position: relative;
}
.promo-content {
  display: flex; align-items: center; gap: 12px;
  animation: promoFade 0.5s ease;
}
@keyframes promoFade {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}
.promo-badge {
  background: linear-gradient(135deg, var(--blue), #7c3aed);
  padding: 3px 10px; border-radius: 4px; font-size: 11px;
  font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px;
}
.promo-text { font-size: 13px; font-weight: 500; }
.promo-link { color: #93c5fd; font-weight: 600; margin-left: 8px; }
.promo-link:hover { color: #bfdbfe; }
.promo-arrow {
  width: 28px; height: 28px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  color: rgba(255,255,255,0.6); transition: all var(--transition);
  background: rgba(255,255,255,0.05);
}
.promo-arrow:hover { background: rgba(255,255,255,0.15); color: #fff; }
.promo-close {
  position: absolute; right: 16px; top: 50%; transform: translateY(-50%);
  color: rgba(255,255,255,0.4); font-size: 18px; line-height: 1;
  transition: color var(--transition);
}
.promo-close:hover { color: rgba(255,255,255,0.8); }

/* ── AI Alerts Bar ── */
.ai-bar {
  border-bottom: 1px solid var(--border);
  background: var(--bg);
}
.ai-bar-inner {
  max-width: 1440px; margin: 0 auto;
  display: flex; align-items: center; gap: 16px;
  padding: 12px 24px;
}
.ai-prompt-box {
  display: flex; align-items: center; gap: 8px;
  flex: 1; max-width: 480px;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: 24px; padding: 6px 16px;
  transition: border-color var(--transition), box-shadow var(--transition);
}
.ai-prompt-box:focus-within {
  border-color: var(--blue);
  box-shadow: 0 0 0 3px rgba(56,97,251,0.1);
}
.ai-prompt-box svg { color: var(--blue); flex-shrink: 0; }
.ai-prompt-box input {
  border: none; outline: none; background: transparent;
  flex: 1; font-size: 13px; color: var(--text);
}
.ai-prompt-box input::placeholder { color: var(--text-tertiary); }
.ai-chips {
  display: flex; align-items: center; gap: 6px;
  overflow-x: auto; flex: 1;
  scrollbar-width: none;
}
.ai-chips::-webkit-scrollbar { display: none; }
.ai-chip {
  padding: 5px 12px; border-radius: 20px;
  background: var(--bg-secondary); border: 1px solid var(--border);
  color: var(--text-secondary); font-size: 12px; font-weight: 500;
  white-space: nowrap; transition: all var(--transition);
  cursor: pointer;
}
.ai-chip:hover { border-color: var(--blue); color: var(--blue); background: var(--blue-light); }

/* ── Main Content ── */
.main-content {
  max-width: 1440px; margin: 0 auto;
  padding: 0 24px;
}

/* ── Filter Tabs ── */
.filter-row {
  display: flex; align-items: center; justify-content: space-between;
  padding: 16px 0 0; gap: 16px; flex-wrap: wrap;
}
.tab-group {
  display: flex; align-items: center; gap: 2px;
  border-bottom: 1px solid var(--border);
}
.tab-group.network { margin-bottom: -1px; }
.tab-btn {
  padding: 8px 16px; font-size: 13px; font-weight: 600;
  color: var(--text-secondary); border-bottom: 2px solid transparent;
  transition: all var(--transition); white-space: nowrap;
  margin-bottom: -1px;
}
.tab-btn:hover { color: var(--text); }
.tab-btn.active {
  color: var(--blue); border-bottom-color: var(--blue);
}

/* ── Category Tabs ── */
.category-row {
  display: flex; align-items: center; gap: 0;
  padding: 12px 0 0;
  border-bottom: 1px solid var(--border);
  margin-bottom: -1px;
}

/* ── Index Tracker ── */
.index-tracker {
  display: flex; align-items: center; gap: 16px;
  padding: 12px 16px; margin-top: 12px;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  font-size: 13px;
}
.index-name { font-weight: 600; color: var(--text); }
.index-symbol { color: var(--text-secondary); font-size: 12px; }
.index-price { font-weight: 600; margin-left: auto; }
.index-change { font-weight: 600; font-size: 12px; min-width: 60px; text-align: right; }
.index-change.positive { color: var(--green); }
.index-change.negative { color: var(--red); }

/* ── Table Controls ── */
.table-controls {
  display: flex; align-items: center; gap: 8px;
  padding: 12px 0; flex-wrap: wrap;
}
.sort-btn {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 5px 12px; border-radius: var(--radius-sm);
  font-size: 12px; font-weight: 600; color: var(--text-secondary);
  background: var(--bg-secondary); border: 1px solid var(--border);
  transition: all var(--transition);
}
.sort-btn:hover { border-color: var(--blue); color: var(--blue); }
.sort-btn.active { background: var(--blue-light); border-color: var(--blue); color: var(--blue); }
.sort-btn svg { width: 12px; height: 12px; }
.control-btn {
  display: inline-flex; align-items: center; gap: 4px;
  padding: 5px 12px; border-radius: var(--radius-sm);
  font-size: 12px; font-weight: 600; color: var(--text-secondary);
  background: var(--bg-secondary); border: 1px solid var(--border);
  transition: all var(--transition);
}
.control-btn:hover { border-color: var(--gray); color: var(--text); }
.control-btn.active { background: var(--blue-light); border-color: var(--blue); color: var(--blue); }

/* ── Columns Dropdown ── */
.columns-dropdown {
  position: absolute; top: 100%; right: 0; z-index: 50;
  background: var(--bg); border: 1px solid var(--border);
  border-radius: var(--radius); box-shadow: var(--shadow-lg);
  padding: 8px 0; min-width: 200px;
  display: none;
}
.columns-dropdown.open { display: block; }
.columns-dropdown label {
  display: flex; align-items: center; gap: 8px;
  padding: 6px 16px; font-size: 12px; color: var(--text);
  cursor: pointer; transition: background var(--transition);
}
.columns-dropdown label:hover { background: var(--bg-secondary); }
.columns-dropdown input[type="checkbox"] {
  accent-color: var(--blue); width: 14px; height: 14px;
}
.columns-wrapper { position: relative; }

/* ── Filters Panel ── */
.filters-panel {
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 16px; margin-bottom: 12px;
  display: none; gap: 16px; flex-wrap: wrap;
}
.filters-panel.open { display: flex; }
.filter-group { display: flex; flex-direction: column; gap: 6px; }
.filter-group-label { font-size: 11px; font-weight: 700; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.5px; }
.filter-options { display: flex; gap: 4px; flex-wrap: wrap; }
.filter-option {
  padding: 4px 10px; border-radius: var(--radius-sm);
  font-size: 12px; font-weight: 500; color: var(--text-secondary);
  background: var(--bg); border: 1px solid var(--border);
  transition: all var(--transition); cursor: pointer;
}
.filter-option:hover { border-color: var(--blue); color: var(--blue); }
.filter-option.active { background: var(--blue-light); border-color: var(--blue); color: var(--blue); }

/* ── Crypto Table ── */
.crypto-table-wrapper {
  overflow-x: auto;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  margin-bottom: 12px;
}
.crypto-table {
  width: 100%; border-collapse: collapse;
  font-size: 13px;
}
.crypto-table thead {
  position: sticky; top: 0; z-index: 10;
  background: var(--bg-secondary);
}
.crypto-table th {
  padding: 10px 12px; text-align: right;
  font-size: 11px; font-weight: 700;
  color: var(--text-secondary); text-transform: uppercase;
  letter-spacing: 0.3px; white-space: nowrap;
  border-bottom: 1px solid var(--border);
  user-select: none; cursor: pointer;
}
.crypto-table th:hover { color: var(--text); }
.crypto-table th:first-child { text-align: center; width: 50px; }
.crypto-table th:nth-child(2) { text-align: left; }
.crypto-table th.sort-active { color: var(--blue); }
.crypto-table th .sort-icon { display: inline-block; margin-left: 2px; opacity: 0.4; font-size: 10px; }
.crypto-table th.sort-active .sort-icon { opacity: 1; }
.crypto-table td {
  padding: 10px 12px; text-align: right;
  border-bottom: 1px solid var(--border-light);
  white-space: nowrap;
}
.crypto-table td:first-child { text-align: center; color: var(--text-secondary); font-weight: 500; }
.crypto-table td:nth-child(2) { text-align: left; }
.crypto-table tbody tr {
  transition: background var(--transition);
}
.crypto-table tbody tr:hover { background: var(--bg-secondary); }
.crypto-table tbody tr:last-child td { border-bottom: none; }

/* Coin name cell */
.coin-name-cell {
  display: flex; align-items: center; gap: 8px;
}
.coin-icon {
  width: 24px; height: 24px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-weight: 700; font-size: 10px; color: #fff; flex-shrink: 0;
}
.coin-name { font-weight: 600; color: var(--text); }
.coin-symbol { color: var(--text-secondary); font-size: 12px; margin-left: 4px; }

/* Price change */
.change-positive { color: var(--green); font-weight: 500; }
.change-negative { color: var(--red); font-weight: 500; }
.change-zero { color: var(--text-secondary); font-weight: 500; }

/* Supply cell */
.supply-cell { color: var(--text-secondary); }
.supply-symbol { color: var(--text-tertiary); }

/* Sparkline cell */
.sparkline-cell { width: 120px; min-width: 120px; }
.sparkline-cell svg { display: block; }

/* Market cap / volume */
.mcap-cell, .vol-cell { font-weight: 500; }

/* ── Pagination ── */
.pagination {
  display: flex; align-items: center; justify-content: space-between;
  padding: 12px 0 24px; flex-wrap: wrap; gap: 12px;
}
.pagination-info { font-size: 13px; color: var(--text-secondary); }
.pagination-pages { display: flex; align-items: center; gap: 4px; }
.page-btn {
  min-width: 32px; height: 32px;
  display: flex; align-items: center; justify-content: center;
  border-radius: var(--radius-sm); font-size: 13px; font-weight: 500;
  color: var(--text-secondary); transition: all var(--transition);
  border: 1px solid transparent;
}
.page-btn:hover { background: var(--bg-secondary); border-color: var(--border); }
.page-btn.active {
  background: var(--blue); color: #fff;
  border-color: var(--blue);
}
.page-ellipsis { color: var(--text-tertiary); padding: 0 4px; font-size: 13px; }

/* ── Market Summary ── */
.market-summary {
  max-width: 1440px; margin: 0 auto;
  padding: 32px 24px;
  border-top: 1px solid var(--border);
}
.market-summary h2 {
  font-family: var(--font-display);
  font-size: 20px; font-weight: 700; margin-bottom: 12px;
}
.market-summary p {
  color: var(--text-secondary); font-size: 13px; line-height: 1.7;
  max-width: 800px;
}
.market-summary .summary-expanded { display: none; margin-top: 8px; }
.market-summary .expanded .summary-expanded { display: block; }
.read-more {
  color: var(--blue); font-weight: 600; font-size: 13px;
  cursor: pointer; border: none; background: none;
  padding: 0; margin-top: 4px;
}
.read-more:hover { text-decoration: underline; }

/* ── Info Content ── */
.info-content {
  max-width: 1440px; margin: 0 auto;
  padding: 32px 24px;
  border-top: 1px solid var(--border);
}
.info-content h2 {
  font-family: var(--font-display);
  font-size: 20px; font-weight: 700; margin-bottom: 8px;
}
.info-content h3 {
  font-size: 15px; font-weight: 600; margin: 16px 0 6px;
}
.info-content p {
  color: var(--text-secondary); font-size: 13px; line-height: 1.7;
  max-width: 800px;
}

/* ── Footer ── */
.footer {
  background: var(--bg-secondary);
  border-top: 1px solid var(--border);
  padding: 40px 24px 24px;
  margin-top: 40px;
}
.footer-inner {
  max-width: 1440px; margin: 0 auto;
  display: grid; grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}
.footer-col h4 {
  font-size: 12px; font-weight: 700; text-transform: uppercase;
  letter-spacing: 0.5px; color: var(--text); margin-bottom: 12px;
}
.footer-col a {
  display: block; color: var(--text-secondary); font-size: 13px;
  padding: 3px 0; transition: color var(--transition);
}
.footer-col a:hover { color: var(--blue); }
.footer-bottom {
  max-width: 1440px; margin: 24px auto 0;
  padding-top: 16px; border-top: 1px solid var(--border);
  font-size: 12px; color: var(--text-tertiary);
  text-align: center;
}

/* ── Scrollbar ── */
.crypto-table-wrapper::-webkit-scrollbar { height: 6px; }
.crypto-table-wrapper::-webkit-scrollbar-track { background: var(--bg-secondary); }
.crypto-table-wrapper::-webkit-scrollbar-thumb { background: var(--gray-light); border-radius: 3px; }
.crypto-table-wrapper::-webkit-scrollbar-thumb:hover { background: var(--gray); }

/* ── Responsive ── */
@media (max-width: 1200px) {
  .footer-inner { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 768px) {
  .nav-links { display: none; }
  .top-bar-inner { gap: 16px; }
  .filter-row { flex-direction: column; align-items: flex-start; }
  .tab-group { overflow-x: auto; width: 100%; }
  .ai-bar-inner { flex-direction: column; align-items: stretch; }
  .ai-prompt-box { max-width: none; }
  .ai-chips { flex-wrap: nowrap; }
  .footer-inner { grid-template-columns: 1fr; gap: 24px; }
  .metric-divider { display: none; }
  .top-bar-inner { flex-wrap: wrap; }
  .index-tracker { flex-wrap: wrap; }
  .table-controls { overflow-x: auto; }
  .pagination { flex-direction: column; align-items: center; }
}
@media (max-width: 480px) {
  html { font-size: 13px; }
  .nav-inner { padding: 0 12px; }
  .top-bar-inner { padding: 8px 12px; }
  .main-content { padding: 0 12px; }
  .promo-inner { padding: 10px 12px; }
  .ai-bar-inner { padding: 8px 12px; }
  .market-summary, .info-content { padding: 24px 12px; }
  .footer { padding: 24px 12px; }
}

/* ── Star / Watchlist ── */
.star-btn {
  background: none; border: none; cursor: pointer;
  padding: 2px; color: var(--gray-light);
  transition: color var(--transition);
  display: flex; align-items: center;
}
.star-btn:hover, .star-btn.active { color: #f5a623; }
.star-btn svg { width: 14px; height: 14px; }
</style>
</head>
<body>

<!-- Navigation -->
<nav class="nav">
  <div class="nav-inner">
    <a href="index.html" class="nav-brand">
      <svg width="28" height="28" viewBox="0 0 28 28" fill="none"><circle cx="14" cy="14" r="14" fill="#3861FB"/><path d="M8 14L12 10L16 14L12 18Z" fill="#fff"/><path d="M12 14L16 10L20 14L16 18Z" fill="rgba(255,255,255,0.6)"/></svg>
      CoinTracker Pro
    </a>
    <div class="nav-links">
      <a href="index.html" class="active">Cryptocurrencies</a>
      <a href="index.html">Dashboards</a>
      <a href="index.html">Exchanges</a>
      <a href="index.html">DexScan</a>
      <a href="index.html">More</a>
    </div>
    <div class="nav-auth">
      <button class="btn-login">Log In</button>
      <button class="btn-signup">Sign Up</button>
    </div>
  </div>
</nav>

<!-- Top Bar Metrics -->
<div class="top-bar">
  <div class="top-bar-inner tabular-nums">
    <div class="metric">
      <span class="metric-label">Market Cap</span>
      <span class="metric-value">$2.56T</span>
      <span class="metric-change positive">↑ 1.46%</span>
    </div>
    <div class="metric-divider"></div>
    <div class="metric">
      <span class="metric-label">CTP20 Index</span>
      <span class="metric-value">$155.36</span>
      <span class="metric-change positive">↑ 1.5%</span>
    </div>
    <div class="metric-divider"></div>
    <div class="metric">
      <span class="metric-label">Fear & Greed</span>
      <span class="metric-value">57</span>
      <span class="metric-badge neutral">Neutral</span>
