// Seeded pseudo-random for consistent change values
function seededRandom(seed) {
  let s = seed;
  return function() {
    s = (s * 16807 + 0) % 2147483647;
    return (s - 1) / 2147483646;
  };
}

function generateCoins() {
  return COINS_RAW.map((c, i) => {
    const rng = seededRandom(i * 7919 + 42);
    const change1h = ((rng() - 0.45) * 3).toFixed(2);
    const change24h = ((rng() - 0.4) * 12).toFixed(2);
    const change7d = ((rng() - 0.35) * 20).toFixed(2);
    // sparkline: 7 points based on price and 7d change
    const p = c[2];
    const d7 = parseFloat(change7d);
    const start = p / (1 + d7 / 100);
    const pts = [];
    for (let j = 0; j < 7; j++) {
      const t = j / 6;
      const base = start + (p - start) * t;
      const noise = base * ((rng() - 0.5) * 0.02);
      pts.push(base + noise);
    }
    pts[6] = p;
    return {
      rank: i + 1,
      name: c[0],
      symbol: c[1],
      price: c[2],
      change1h: parseFloat(change1h),
      change24h: parseFloat(change24h),
      change7d: parseFloat(change7d),
      marketCap: c[3] * 1e9,
      volume24h: c[4] * 1e9,
      circulatingSupply: c[5],
      network: c[6],
      color: c[7],
      categories: c[8] || [0],
      sparkline: pts,
      starred: c[8] && c[8].includes(2)
    };
  });
}

const allCoins = generateCoins();

// ─── State ───
const state = {
  network: 'All Networks',
  category: 'Top',
  sort: 'marketCap',
  sortDir: 'desc',
  page: 1,
  perPage: 100,
  totalCoins: 8364,
  columns: COLUMNS.map(c => ({ ...c, visible: true })),
  filters: {
    marketCapFilter: 'all',
    changeFilter: 'all',
    priceFilter: 'all'
  },
  promoIndex: 0,
};

// ─── Helpers ───
function formatPrice(p) {
  if (p >= 1000) return '$' + p.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (p >= 1) return '$' + p.toFixed(2);
  if (p >= 0.01) return '$' + p.toFixed(4);
  if (p >= 0.0001) return '$' + p.toFixed(6);
  return '$' + p.toFixed(8);
}

function formatLargeNum(n) {
  if (n >= 1e12) return '$' + (n/1e12).toFixed(2) + 'T';
  if (n >= 1e9) return '$' + (n/1e9).toFixed(2) + 'B';
  if (n >= 1e6) return '$' + (n/1e6).toFixed(2) + 'M';
  return '$' + n.toLocaleString('en-US');
}

function formatPercent(v) {
  const sign = v > 0 ? '+' : '';
  return sign + v.toFixed(2) + '%';
}

function changeClass(v) {
  if (v > 0) return 'change-positive';
  if (v < 0) return 'change-negative';
  return 'change-zero';
}

function createSparklineSVG(points, isPositive) {
  const w = 120, h = 36, pad = 2;
  const min = Math.min(...points);
  const max = Math.max(...points);
  const range = max - min || 1;
  const coords = points.map((p, i) => {
    const x = pad + (i / (points.length - 1)) * (w - 2 * pad);
    const y = pad + (1 - (p - min) / range) * (h - 2 * pad);
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  });
  const color = isPositive ? 'var(--green)' : 'var(--red)';
  const fillColor = isPositive ? 'rgba(22,199,132,0.1)' : 'rgba(234,57,67,0.1)';
  const linePoints = coords.join(' ');
  const areaPoints = linePoints + ` ${(w - pad).toFixed(1)},${(h - pad).toFixed(1)} ${pad},${(h - pad).toFixed(1)}`;
  return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg">
    <polygon points="${areaPoints}" fill="${fillColor}"/>
    <polyline points="${linePoints}" fill="none" stroke="${color}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
  </svg>`;
}

// ─── Rendering ───
function getFilteredCoins() {
  let coins = [...allCoins];

  // Network filter
  if (state.network !== 'All Networks') {
    const netMap = { 'BSC':'bsc', 'Solana':'solana', 'Base':'base', 'Ethereum':'ethereum' };
    const net = netMap[state.network];
    if (net) coins = coins.filter(c => c.network === net);
    else if (state.network === 'More') coins = coins.filter(c => !['bitcoin','ethereum','bsc','solana','base'].includes(c.network));
  }

  // Category filter
  const catMap = { 'Top':0, 'Trending':1, 'Watchlist':2, 'Prediction Markets':3, 'Most Visited':4, 'New':5 };
  const catIdx = catMap[state.category];
  if (catIdx !== undefined) {
    if (state.category === 'Watchlist') {
      coins = coins.filter(c => c.starred);
    } else {
      coins = coins.filter(c => c.categories.includes(catIdx));
    }
  }

  // Advanced filters
  if (state.filters.marketCapFilter !== 'all') {
    const f = state.filters.marketCapFilter;
    if (f === 'mega') coins = coins.filter(c => c.marketCap >= 50e9);
    else if (f === 'large') coins = coins.filter(c => c.marketCap >= 10e9 && c.marketCap < 50e9);
    else if (f === 'mid') coins = coins.filter(c => c.marketCap >= 1e9 && c.marketCap < 10e9);
    else if (f === 'small') coins = coins.filter(c => c.marketCap < 1e9);
  }
  if (state.filters.changeFilter !== 'all') {
    if (state.filters.changeFilter === 'gainers') coins = coins.filter(c => c.change24h > 0);
    else if (state.filters.changeFilter === 'losers') coins = coins.filter(c => c.change24h < 0);
  }
  if (state.filters.priceFilter !== 'all') {
    const f = state.filters.priceFilter;
    if (f === 'under1') coins = coins.filter(c => c.price < 1);
    else if (f === 'b1to100') coins = coins.filter(c => c.price >= 1 && c.price <= 100);
    else if (f === 'over100') coins = coins.filter(c => c.price > 100);
  }

  // Sort
  coins.sort((a, b) => {
    let va = a[state.sort], vb = b[state.sort];
    if (typeof va === 'string') { va = va.toLowerCase(); vb = vb.toLowerCase(); }
    return state.sortDir === 'desc' ? (vb > va ? 1 : vb < va ? -1 : 0) : (va > vb ? 1 : va < vb ? -1 : 0);
  });

  return coins;
}

function renderTable() {
  const coins = getFilteredCoins();
  const visibleCols = state.columns.filter(c => c.visible);

  // Header
  const thead = document.getElementById('cryptoTableHead');
  thead.innerHTML = '<tr>' + visibleCols.map(col => {
    const isActive = state.sort === col.key;
    const arrow = isActive ? (state.sortDir === 'desc' ? '▼' : '▲') : '▾';
    return `<th class="${isActive ? 'sort-active' : ''}" data-key="${col.key}" onclick="setSort('${col.key}')">${col.label} <span class="sort-icon">${arrow}</span></th>`;
  }).join('') + '</tr>';

  // Body
  const tbody = document.getElementById('cryptoTableBody');
  const start = (state.page - 1) * state.perPage;
  const pageCoins = coins.slice(start, start + state.perPage);

  if (pageCoins.length === 0) {
    tbody.innerHTML = `<tr><td colspan="${visibleCols.length}" style="text-align:center;padding:40px;color:var(--text-secondary);">No cryptocurrencies match your filters</td></tr>`;
  } else {
    tbody.innerHTML = pageCoins.map(coin => {
      const cells = visibleCols.map(col => {
        switch(col.key) {
          case 'rank': return `<td>${coin.rank}</td>`;
          case 'name': return `<td><div class="coin-name-cell"><button class="star-btn ${coin.starred?'active':''}" onclick="toggleStar(${coin.rank-1})" title="Add to watchlist"><svg viewBox="0 0 16 16" fill="${coin.starred?'#f5a623':'none'}" stroke="${coin.starred?'#f5a623':'currentColor'}" stroke-width="1.5"><path d="M8 1.5l1.85 3.75 4.15.6-3 2.93.71 4.12L8 10.87l-3.71 2.03.71-4.12-3-2.93 4.15-.6z"/></svg></button><span class="coin-icon" style="background:${coin.color}">${coin.symbol.charAt(0)}</span><span class="coin-name">${coin.name}</span><span class="coin-symbol">${coin.symbol}</span></div></td>`;
          case 'price': return `<td style="font-weight:500">${formatPrice(coin.price)}</td>`;
          case 'change1h': return `<td class="${changeClass(coin.change1h)}">${formatPercent(coin.change1h)}</td>`;
          case 'change24h': return `<td class="${changeClass(coin.change24h)}">${formatPercent(coin.change24h)}</td>`;
          case 'change7d': return `<td class="${changeClass(coin.change7d)}">${formatPercent(coin.change7d)}</td>`;
          case 'marketCap': return `<td class="mcap-cell">${formatLargeNum(coin.marketCap)}</td>`;
          case 'volume24h': return `<td class="vol-cell">${formatLargeNum(coin.volume24h)}</td>`;
          case 'circulatingSupply': return `<td class="supply-cell">${coin.circulatingSupply}</td>`;
          case 'sparkline': return `<td class="sparkline-cell">${createSparklineSVG(coin.sparkline, coin.change7d >= 0)}</td>`;
          default: return '<td></td>';
        }
      });
      return `<tr>${cells.join('')}</tr>`;
    }).join('');
  }

  // Pagination
  const totalFiltered = coins.length;
  const totalPages = Math.ceil(state.totalCoins / state.perPage);
  const end = Math.min(start + state.perPage, totalFiltered);
  document.getElementById('paginationInfo').textContent = totalFiltered > 0
    ? `Showing ${start+1}–${end} of ${totalFiltered.toLocaleString()} assets`
    : 'No results';

  const pp = document.getElementById('paginationPages');
  let pages = [];
  for (let i = 1; i <= Math.min(4, totalPages); i++) pages.push(i);
  if (totalPages > 4) { pages.push('...'); pages.push(totalPages); }
  pp.innerHTML = pages.map(p => {
    if (p === '...') return '<span class="page-ellipsis">...</span>';
    return `<button class="page-btn ${p===state.page?'active':''}" onclick="setPage(${p})">${p}</button>`;
  }).join('');
}

function renderNetworkTabs() {
  const container = document.getElementById('networkTabs');
  container.innerHTML = NETWORKS.map(n =>
    `<button class="tab-btn ${n===state.network?'active':''}" onclick="setNetwork('${n}')">${n}</button>`
  ).join('');
}

function renderCategoryTabs() {
  const container = document.getElementById('categoryTabs');
  container.innerHTML = CATEGORIES.map(c =>
    `<button class="tab-btn ${c===state.category?'active':''}" onclick="setCategory('${c}')">${c}</button>`
  ).join('');
}

function renderColumnsDropdown() {
  const dd = document.getElementById('columnsDropdown');
  dd.innerHTML = state.columns.filter(c => !c.required).map(col =>
    `<label><input type="checkbox" ${col.visible?'checked':''} onchange="toggleColumn('${col.key}')"> ${col.label}</label>`
  ).join('');
}

function renderAiChips() {
  document.getElementById('aiChips').innerHTML = AI_CHIPS.map(c =>
    `<button class="ai-chip" onclick="document.getElementById('aiInput').value='${c}'">${c}</button>`
  ).join('');
}

function renderPromo() {
  const p = PROMOS[state.promoIndex];
  document.getElementById('promoContent').innerHTML =
    `<span class="promo-badge">${p.badge}</span><span class="promo-text">${p.text}</span><a href="#" class="promo-link">${p.link} →</a>`;
}

// ─── Actions ───
function setNetwork(n) {
  state.network = n;
  state.page = 1;
  renderNetworkTabs();
  renderTable();
}

function setCategory(c) {
  state.category = c;
  state.page = 1;
  renderCategoryTabs();
  renderTable();
}

function setSort(key) {
  if (state.sort === key) {
    state.sortDir = state.sortDir === 'desc' ? 'asc' : 'desc';
  } else {
    state.sort = key;
    state.sortDir = 'desc';
  }
  state.page = 1;
  // Update sort button styles
  document.querySelectorAll('.sort-btn').forEach(b => b.classList.toggle('active', b.dataset.sort === key));
  renderTable();
}

function setPage(p) {
  state.page = p;
  renderTable();
  document.querySelector('.crypto-table-wrapper').scrollIntoView({ behavior: 'smooth' });
}

function toggleColumns() {
  const dd = document.getElementById('columnsDropdown');
  dd.classList.toggle('open');
  document.getElementById('columnsBtn').classList.toggle('active', dd.classList.contains('open'));
}

function toggleColumn(key) {
  const col = state.columns.find(c => c.key === key);
  if (col) col.visible = !col.visible;
  renderTable();
}

function toggleFilters() {
  const panel = document.getElementById('filtersPanel');
  panel.classList.toggle('open');
  document.getElementById('filtersBtn').classList.toggle('active', panel.classList.contains('open'));
}

function toggleMarketSummary(btn) {
  const section = document.getElementById('marketSummary');
  section.classList.toggle('expanded');
  btn.textContent = section.classList.contains('expanded') ? 'Read Less' : 'Read More';
}

function toggleStar(idx) {
  if (idx >= 0 && idx < allCoins.length) {
    allCoins[idx].starred = !allCoins[idx].starred;
    renderTable();
  }
}

function promoSlide(dir) {
  state.promoIndex = (state.promoIndex + dir + PROMOS.length) % PROMOS.length;
  renderPromo();
}

// Filter options
document.querySelectorAll('.filter-options').forEach(group => {
  const filterKey = group.dataset.filter;
  group.querySelectorAll('.filter-option').forEach(btn => {
    btn.addEventListener('click', () => {
      group.querySelectorAll('.filter-option').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      state.filters[filterKey] = btn.dataset.value;
      state.page = 1;
      renderTable();
    });
  });
});

// Close columns dropdown on outside click
document.addEventListener('click', (e) => {
  if (!e.target.closest('.columns-wrapper')) {
    document.getElementById('columnsDropdown').classList.remove('open');
    document.getElementById('columnsBtn').classList.remove('active');
  }
});

// Promo auto-rotation
setInterval(() => promoSlide(1), 5000);

// ─── Init ───
renderNetworkTabs();
renderCategoryTabs();
renderColumnsDropdown();
renderAiChips();
renderPromo();
renderTable();
</script>

</body>
</html>
